CREATE TABLE IF NOT EXISTS public.break_glass_overrides ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hospital_id UUID NOT NULL REFERENCES public.hospitals(id) ON DELETE CASCADE, triggered_by_user_id UUID NOT NULL REFERENCES public.profiles(user_id) ON DELETE RESTRICT, approved_by_role TEXT NOT NULL CHECK (approved_by_role IN ('emergency_physician', 'icu_nurse', 'head_pharmacist', 'admin')), patient_id UUID NOT NULL REFERENCES public.patients(id) ON DELETE RESTRICT, override_type TEXT NOT NULL CHECK (override_type IN ( 'emergency_medication_dispense', 'critical_discharge', 'lab_override_critical_value', 'system_unavailable_workaround', 'clinical_judgment_override' )), emergency_level TEXT NOT NULL CHECK (emergency_level IN ('critical', 'urgent', 'time_sensitive')), reason_sanitized TEXT NOT NULL, reason_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'expired', 'revoked')), escalated_to_admin BOOLEAN DEFAULT FALSE, escalation_timestamp TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), expires_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ DEFAULT now() ); CREATE INDEX IF NOT EXISTS idx_break_glass_hospital_status ON public.break_glass_overrides(hospital_id, status); CREATE INDEX IF NOT EXISTS idx_break_glass_patient_active ON public.break_glass_overrides(patient_id) WHERE status = 'active'; CREATE INDEX IF NOT EXISTS idx_break_glass_expires ON public.break_glass_overrides(expires_at) WHERE status = 'active'; ALTER TABLE public.break_glass_overrides ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "break_glass_hospital_scope" ON break_glass_overrides; CREATE POLICY "break_glass_hospital_scope" ON public.break_glass_overrides USING (hospital_id = (SELECT hospital_id FROM profiles WHERE id = auth.uid())); DROP POLICY IF EXISTS "break_glass_role_restriction" ON break_glass_overrides; CREATE POLICY "break_glass_role_restriction" ON public.break_glass_overrides USING ( EXISTS ( SELECT 1 FROM public.user_roles ur WHERE ur.user_id = auth.uid() AND ur.role IN ('admin', 'doctor', 'nurse', 'pharmacist') AND ur.hospital_id = break_glass_overrides.hospital_id ) ); CREATE OR REPLACE FUNCTION public.expire_break_glass_overrides() RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $fn$ BEGIN UPDATE public.break_glass_overrides SET status = 'expired' WHERE status = 'active' AND expires_at < now(); END; $fn$; CREATE OR REPLACE FUNCTION public.touch_row_updated_at() RETURNS trigger LANGUAGE plpgsql AS $fn$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $fn$; DROP TRIGGER IF EXISTS break_glass_updated_at ON public.break_glass_overrides; CREATE TRIGGER break_glass_updated_at BEFORE UPDATE ON public.break_glass_overrides FOR EACH ROW EXECUTE FUNCTION public.touch_row_updated_at();